(8300000000000003021,'𤯌',1,'gan1','甘部',0,'{"fanqie": "古三切", "meaning": "和也。从甘从麻。麻，調也。甘亦聲。讀若函。", "source": "说文解字"}','说文解字'),
(8300000000000003022,'猒',1,'yan1/yan4','甘部',0,'{"fanqie": "於鹽切", "meaning": "飽也。从甘从肰。", "source": "说文解字"}','说文解字'),
(8300000000000003023,'甚',1,'shen4','甘部',0,'{"fanqie": "常枕切", "meaning": "尤安樂也。从甘，从匹耦也。", "source": "说文解字"}','说文解字'),
(8300000000000003024,'曰',1,'yue4','曰部',0,'{"fanqie": "王代切", "meaning": "詞也。从口乙聲。亦象口气出也。凡曰之屬皆从曰。", "source": "说文解字"}','说文解字'),
(8300000000000003025,'𣆑',1,'ce4','曰部',0,'{"fanqie": "楚革切", "meaning": "告也。从曰从冊，冊亦聲。", "source": "说文解字"}','说文解字'),
(8300000000000003026,'曷',1,'he2','曰部',0,'{"fanqie": "胡葛切", "meaning": "何也。从曰匃聲。", "source": "说文解字"}','说文解字'),
(8300000000000003027,'曶',1,'hu1','曰部',0,'{"fanqie": "呼骨切", "meaning": "出气詞也。从曰，象气出形。《春秋傳》曰：\"鄭太子曶。\"", "source": "说文解字"}','说文解字'),
(8300000000000003028,'朁',1,'can3','曰部',0,'{"fanqie": "七感切", "meaning": "曾也。从曰兓聲。《詩》曰：\"朁不畏明。\"", "source": "说文解字"}','说文解字'),
(8300000000000003029,'沓',1,'ta4/da2','曰部',0,'{"fanqie": "徒合切", "meaning": "語多沓沓也。从水从曰。遼東有沓縣。", "source": "说文解字"}','说文解字'),
(8300000000000003030,'曹',1,'cao2','曰部',0,'{"fanqie": "昨牢切", "meaning": "獄之兩曹也。在廷東。从□，治事者；从曰。", "source": "说文解字"}','说文解字'),
(8300000000000003031,'乃',1,'nai3','乃部',0,'{"fanqie": "奴亥切", "meaning": "曳詞之難也。象气之出難。凡□之屬皆从□。", "source": "说文解字"}','说文解字'),
(8300000000000003032,'𠧟',1,'reng2','乃部',0,'{"fanqie": "如乘切", "meaning": "驚聲也。从乃省，西聲。籀文□不省。或曰□，往也。讀若仍。", "source": "说文解字"}','说文解字'),
(8300000000000003033,'𠧴',1,'you2','乃部',0,'{"fanqie": "以周切", "meaning": "气行皃。从乃□聲。讀若攸。", "source": "说文解字"}','说文解字'),
(8300000000000003034,'丂',1,'kao3','丂部',0,'{"fanqie": "苦浩切", "meaning": "气欲舒出。□上礙於一也。丂，古文以爲亏字，又以爲巧字。凡丂之屬皆从丂。", "source": "说文解字"}','说文解字'),
(8300000000000003035,'甹',1,'ping1','丂部',0,'{"fanqie": "普丁切", "meaning": "亟詞也。从丂从由。或曰甹，俠也。三輔謂輕財者爲甹。", "source": "说文解字"}','说文解字'),
(8300000000000003036,'寧',1,'ning2/ning4','丂部',0,'{"fanqie": "奴丁切", "meaning": "願詞也。从丂寍聲。", "source": "说文解字"}','说文解字'),
(8300000000000003037,'𠀀',1,'he1','丂部',0,'{"fanqie": "虎何切", "meaning": "反丂也。讀若呵。", "source": "说文解字"}','说文解字'),
(8300000000000003038,'可',1,'ke3','可部',0,'{"fanqie": "肯我切", "meaning": "□也。从口丂，丂亦聲。凡可之屬皆从可。", "source": "说文解字"}','说文解字'),
(8300000000000003039,'奇',1,'qi2/ji1','可部',0,'{"fanqie": "渠羈切", "meaning": "異也。一曰不耦。从大从可。", "source": "说文解字"}','说文解字'),
(8300000000000003040,'哿',1,'ge3','可部',0,'{"fanqie": "古我切", "meaning": "可也。从可加聲。《詩》曰：\"哿矣富人。\"", "source": "说文解字"}','说文解字'),
(8300000000000003041,'哥',1,'ge1','可部',0,'{"fanqie": "古俄切", "meaning": "聲也。从二可。古文以爲謌字。", "source": "说文解字"}','说文解字'),
(8300000000000003042,'叵',1,'po3','可部',0,'{"fanqie": "普火切", "meaning": "不可也。从反可。", "source": "说文解字"}','说文解字'),
(8300000000000003043,'兮',1,'xi1','兮部',0,'{"fanqie": "胡雞切", "meaning": "語所稽也。从丂，八象气越亏也。凡兮之屬皆从兮。", "source": "说文解字"}','说文解字'),
